-- Preserve the old directory's ownership check before retiring its parent tables.
update "platform_app_credentials" set "revoked_at" = max("platform_app_credentials"."issued_at",unixepoch()*1000) where ("platform_app_credentials"."revoked_at" is null and not exists (select 1 from "platform_apps" inner join "platform_tenants" on "platform_tenants"."tenant_id" = "platform_apps"."tenant_id" where ("platform_apps"."app_id" = "platform_app_credentials"."app_id" and "platform_apps"."lifecycle" = 'active')));--> statement-breakpoint
update "platform_projects" set "lifecycle" = 'deleted', "deleted_at" = max("platform_projects"."created_at",unixepoch()*1000), "updated_at" = max("platform_projects"."created_at",unixepoch()*1000) where ("platform_projects"."lifecycle" = 'active' and not exists (select 1 from "platform_apps" inner join "platform_tenants" on "platform_tenants"."tenant_id" = "platform_apps"."tenant_id" where ("platform_apps"."app_id" = "platform_projects"."app_id" and "platform_apps"."lifecycle" = 'active')));
